import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import * as T from './three.module.js';import {createGrainTrailer} from './trailer-model.js?v=simulation15';import {FEED_STORE,MILLS,ensureLogistics,buyGrainTrailer,attachGrainTrailer,detachGrainTrailer,startFeedMill,beginBulkTransfer,cancelBulkTransfer,updateBulkTransfer} from './production-logistics.js?v=simulation15';
export function installProduction({scene,state,save,modal,toast,player,vehicles,register,block,sign,blocked,preview=()=>{}}){
 const steel=new T.MeshStandardMaterial({color:'#9baaa8',metalness:.25,roughness:.65}),dark=new T.MeshStandardMaterial({color:'#4c625e',roughness:.8}),concrete=new T.MeshStandardMaterial({color:'#a9aa99',roughness:1}),paint=new T.MeshStandardMaterial({color:'#d6b761',roughness:.7});let elapsed=0,lastSave=0,lastTrailer=null;
 function cube(parent,w,h,d,mat,x,y,z){const o=new T.Mesh(new T.BoxGeometry(w,h,d),mat);o.position.set(x,y,z);o.receiveShadow=true;parent.add(o);return o;}
 function pipe(parent,a,b,r=.16){const from=new T.Vector3(...a),to=new T.Vector3(...b),delta=to.clone().sub(from),o=new T.Mesh(new T.CylinderGeometry(r,r,delta.length(),12),steel);o.position.copy(from.add(to).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());parent.add(o);return o;}
 const trailer=createGrainTrailer();scene.add(trailer.root);register(trailer.root,{kind:'production',productionId:'trailer',x:-41,z:17,approach:{x:-44,z:17}});
 function bay(name,p){const root=new T.Group();root.name=name;scene.add(root);cube(root,4.4,.08,10.5,concrete,p.x,.24,p.z+2.5);for(const side of [-1,1])cube(root,.13,.025,10,paint,p.x+side*2,.3,p.z+2.5);for(const dz of [-1.5,1.5])cube(root,3.9,.025,.12,paint,p.x,.3,p.z+dz);return root;}
 const store=bay('Farm bulk feed and maize storage',FEED_STORE.bay);const silo=new T.Mesh(new T.CylinderGeometry(1.8,1.8,6,24),steel);silo.position.set(FEED_STORE.x,3.25,FEED_STORE.z);store.add(silo);const cap=new T.Mesh(new T.ConeGeometry(1.83,1.3,24),dark);cap.position.set(FEED_STORE.x,6.9,FEED_STORE.z);store.add(cap);block(FEED_STORE.x,FEED_STORE.z,3.6,3.6);pipe(store,[FEED_STORE.x,5,FEED_STORE.z],[FEED_STORE.bay.x,3.4,FEED_STORE.bay.z]);sign('FEED & GRAIN STORE',FEED_STORE.x,8,FEED_STORE.z);register(store,{kind:'production',productionId:'store',x:FEED_STORE.x,z:FEED_STORE.z,approach:{x:-23,z:32}});
 const fixed=[store],flows=[];for(const [id,spec]of Object.entries(MILLS)){const root=bay(spec.name+' drive-through intake and feed outlet',spec.bay),{x,z}=spec.bay,h=id==='home'?3.1:4.7,sourceX=id==='home'?-18:79;
 pipe(root,[sourceX,h,z],[x,h,z]);pipe(root,[x,h,z],[x,2.5,z]);const funnel=new T.Mesh(new T.CylinderGeometry(.45,.15,.65,12),steel);funnel.position.set(x,2.6,z);root.add(funnel);
 // Supports remain outside the 3.8 m vehicle/trailer lane.
 for(const side of [-1,1]){cube(root,.16,h,.16,dark,x+side*2.25,h/2+.2,z);block(x+side*2.25,z,.16,.16);}cube(root,4.6,.18,.18,dark,x,h,z);
 const grate=cube(root,2.4,.05,2.4,dark,x,.32,z);for(let i=0;i<10;i++)cube(root,2.2,.025,.06,steel,x,.36,z-1+i*.22);sign(id==='home'?'MILL · INTAKE / FEED OUTLET':'BULK FEED LOADING',x,h+1.5,z);register(root,{kind:'production',productionId:id,x,z,approach:{x:x-3,z:z+4}});
 fixed.push(root);const positions=new Float32Array(90*3),geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));const particles=new T.Points(geometry,new T.PointsMaterial({color:'#dfc384',size:.08,transparent:true,opacity:.9}));particles.frustumCulled=false;root.add(particles);flows.push({id,particles,positions,x,z});}
 // Batch the fixed industrial structures; tipping and grain streams remain animated.
 for(const group of fixed){group.updateMatrixWorld(true);const buckets=new Map(),old=[];group.traverse(o=>{if(o.isMesh){old.push(o);const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrix);if(!buckets.has(o.material))buckets.set(o.material,[]);buckets.get(o.material).push(geo);}});for(const o of old)o.removeFromParent();for(const [mat,list]of buckets){const mesh=new T.Mesh(mergeGeometries(list),mat);mesh.receiveShadow=true;group.add(mesh);for(const g of list)g.dispose();}if(group.userData.station)register(group,group.userData.station);}
 function safe(action,reopen=true){try{if(Math.abs(vehicles.speed)>.12)throw Error('Stop your tow vehicle before handling grain or the trailer.');action();save();if(reopen)window.openProduction(lastPanel);return true;}catch(e){toast(e.message);return false;}}
 let lastPanel='store';window.viewProductionBay=()=>{const tr=ensureLogistics(state).trailer;preview(lastPanel==='trailer'?tr:MILLS[lastPanel]?.bay||FEED_STORE.bay);document.querySelector('dialog').close();};
 window.openProduction=(id='store')=>{lastPanel=id;const l=ensureLogistics(state),tr=l.trailer,m=l.mills[id],spec=MILLS[id];modal('<span class="service-tag">BULK FARM LOGISTICS</span><h2>'+(spec?spec.name:id==='trailer'?'Grain trailer':'Feed & grain store')+'</h2><button onclick="viewProductionBay()">Show this loading bay / trailer</button><p class="production-route">Farm maize → mill intake → milling → feed outlet → farm feed storage</p><p>Trailer: '+(tr.owned?(tr.attachedTo?'attached to '+tr.attachedTo:'parked at garage / last location')+' · '+tr.quantity+' / '+tr.capacity+' '+(tr.good||'units'):'not purchased')+'</p>'+(tr.owned?'<div class="choice"><button onclick="hitchBulkTrailer()">'+(tr.attachedTo?'Unhitch trailer':'Hitch trailer to nearby vehicle')+'</button><button onclick="openVehicles()">Vehicles / garage</button></div>':'<button class="primary" onclick="purchaseBulkTrailer()">Buy grain trailer · 250 coins</button><p>Parked at −41, 17. Reverse a tractor or pickup toward its drawbar. The cultivator is stowed while towing.</p>')+(spec?'<article class="county-card"><h3>Mill intake</h3><p>'+m.maize+' maize waiting · '+spec.batch+' maize + '+spec.power+' power → '+spec.batch+' feed · '+spec.seconds+' seconds per batch</p><button onclick="bulkTransfer(\'mill-intake\',\''+id+'\')">Tip trailer maize into intake</button><button id="mill-start-action" class="primary" onclick="operateBulkMill(\''+id+'\')" '+(m.job?'disabled':'')+'>Start milling delivered maize</button><p id="mill-production-status">'+(m.job?'Processing · '+Math.max(0,Math.ceil((m.job.finishAt-Date.now())/1000))+'s remaining':m.feed+' feed ready in outlet silo')+'</p><button onclick="bulkTransfer(\'mill-load\',\''+id+'\')">Load feed beneath outlet</button></article><p>Centre the trailer beneath the spout at '+spec.bay.x+', '+spec.bay.z+'. Keep the trailer centre within 1 metre of the outlet. Transfers take 6 seconds. Driving away cancels the transfer without losing the goods.</p>':'<article class="county-card"><h3>Farm storage</h3><p>'+state.inventory.maize+' maize · '+state.inventory.feed+' feed available for your animals and trade.</p><div class="choice"><button onclick="bulkTransfer(\'farm-load\')">Load up to 20 maize into trailer</button><button class="primary" onclick="bulkTransfer(\'farm-unload\')">Tip trailer cargo into farm storage</button></div><p>Centre the trailer in the storage bay at −23, 26. The tow vehicle is ahead of the trailer.</p></article>')+'<div class="choice"><button onclick="openProduction(\'store\')">Farm storage</button><button onclick="openProduction(\'home\')">Home mill</button><button onclick="openProduction(\'county\')">County mill</button><button onclick="openCountyPlot(\'county-mill\')">Mill ownership</button><button onclick="openCropBeds()">Crop beds</button></div><p>Home mill: Feed miller role. County mill: purchase the property. Feed remains in the mill or trailer until you bring it to your farm. Old inventory is kept. Power represents the connected grid.</p>');};
 window.purchaseBulkTrailer=()=>safe(()=>{if(Math.hypot(player.position.x+35,player.position.z-27)>15)throw Error('Visit the farm garage to buy your trailer.');buyGrainTrailer(state);toast('Trailer ready at −41, 17.');});
 window.hitchBulkTrailer=()=>safe(()=>{const tr=ensureLogistics(state).trailer;if(tr.attachedTo){const v=state.vehicles.owned[tr.attachedTo];if(Math.hypot(player.position.x-v.x,player.position.z-v.z)>6)throw Error('Stand beside your tow vehicle.');detachGrainTrailer(state);}else{const id=vehicles.active||Object.entries(state.vehicles.owned).sort((a,b)=>Math.hypot(a[1].x-player.position.x,a[1].z-player.position.z)-Math.hypot(b[1].x-player.position.x,b[1].z-player.position.z))[0]?.[0],v=state.vehicles.owned[id];if(!v||Math.hypot(player.position.x-v.x,player.position.z-v.z)>6)throw Error('Stand beside the tow vehicle.');attachGrainTrailer(state,id,blocked);}toast('Trailer coupling updated.');});
 window.bulkTransfer=(kind,id='home')=>{if(safe(()=>beginBulkTransfer(state,kind,id),false)){preview(kind.startsWith('farm')?FEED_STORE.bay:MILLS[id].bay);document.querySelector('dialog').close();toast('Bulk transfer started. Keep the trailer still.');}};
 window.operateBulkMill=id=>safe(()=>{startFeedMill(state,id);toast('Mill running. Feed will wait in the outlet silo.');});
 window.cancelFarmTransfer=()=>{cancelBulkTransfer(state);save();toast('Transfer cancelled; goods remain at their source.');};
 return {trailer,tick(dt){elapsed+=dt;const l=ensureLogistics(state),result=updateBulkTransfer(state),f=l.transfer,tr=l.trailer,p=f?Math.min(1,(Date.now()-f.startedAt)/f.durationMs):0;const moved=lastTrailer?Math.hypot(tr.x-lastTrailer.x,tr.z-lastTrailer.z):0;lastTrailer={x:tr.x,z:tr.z};trailer.update(tr,moved*Math.sign(vehicles.speed),f?(['mill-load','farm-load'].includes(f.kind)?f.quantity*p:-f.quantity*p):0,f&&['mill-intake','farm-unload'].includes(f.kind)?Math.sin(p*Math.PI)*.75:0);for(const [id,a]of vehicles.actors){a.setTowing?.(tr.attachedTo===id);}
 for(const flow of flows){flow.particles.visible=!!f&&['mill-load','mill-intake'].includes(f.kind)&&f.mill===flow.id;if(!flow.particles.visible)continue;for(let i=0;i<90;i++){const t=(elapsed*1.4+i/90)%1;const intake=f?.kind==='mill-intake',x=intake?tr.x-Math.sin(tr.heading)*1.6:flow.x,z=intake?tr.z-Math.cos(tr.heading)*1.6:flow.z;flow.positions[i*3]=x+Math.sin(i*2.4)*.13;flow.positions[i*3+1]=intake?1.1-t*.8:2.7-t*1.25;flow.positions[i*3+2]=z+Math.cos(i*2.4)*.13;}flow.particles.geometry.attributes.position.needsUpdate=true;}
 if(MILLS[lastPanel]&&document.querySelector('dialog').open){const m=l.mills[lastPanel],status=document.querySelector('#mill-production-status'),start=document.querySelector('#mill-start-action');if(status)status.textContent=m.job?'Processing · '+Math.max(0,Math.ceil((m.job.finishAt-Date.now())/1000))+'s remaining':m.feed+' feed ready in outlet silo';if(start)start.disabled=!!m.job;}const hud=document.querySelector('#bulk-status');if(hud){hud.hidden=!f;hud.textContent=f?Math.floor(p*100)+'% · '+f.quantity+' '+f.good+' · keep trailer parked':'';}if(result){save();toast(result==='completed'?'Bulk transfer completed.':'Transfer cancelled: trailer moved.');}lastSave+=dt;if(lastSave>10){lastSave=0;if(state.logistics?.trailer?.attachedTo||state.logistics?.transfer||Object.values(state.logistics?.mills||{}).some(m=>m.job))save();}}};
}
